import ConversionKit
import CoreGraphics
import Foundation
import ImageIO

/// The shared fixtures in `Tests/Fixtures/images`, regenerated by
/// `swift Tests/Fixtures/make-images.swift`.
enum Fixtures {
    static let images = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()  // ImageEngineTests
        .deletingLastPathComponent()  // Tests
        .deletingLastPathComponent()  // ImageEngine
        .deletingLastPathComponent()  // Engines
        .deletingLastPathComponent()  // Packages
        .deletingLastPathComponent()  // repository root
        .appendingPathComponent("Tests/Fixtures/images", isDirectory: true)

    static let width = 64
    static let height = 48

    /// The plain 64×48 fixture for a format, `heic-64x48.heic`.
    static func image(_ format: FileFormat) -> URL {
        images.appendingPathComponent("\(format.id)-64x48.\(format.preferredExtension)")
    }

    static let transparentPNG = images.appendingPathComponent("png-transparent.png")
}

/// A fresh folder under the temp directory, deleted when the test is done
/// with it.
final class TemporaryFolder {
    let url: URL

    init() throws {
        url = FileManager.default.temporaryDirectory
            .appendingPathComponent("MorphImageTests-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
    }

    deinit {
        try? FileManager.default.removeItem(at: url)
    }

    /// Copies a fixture in, optionally under another name.
    func copy(_ fixture: URL, as name: String? = nil) throws -> URL {
        let copy = url.appendingPathComponent(name ?? fixture.lastPathComponent)
        try FileManager.default.copyItem(at: fixture, to: copy)
        return copy
    }

    func file(_ name: String) -> URL {
        url.appendingPathComponent(name, isDirectory: false)
    }

    func names() throws -> [String] {
        try FileManager.default.contentsOfDirectory(atPath: url.path).sorted()
    }
}

/// What ImageIO makes of a converted file — the "opens with the native reader"
/// check from SPEC §11.
struct DecodedImage {
    let typeIdentifier: String
    let width: Int
    let height: Int
    let properties: [CFString: Any]
    let image: CGImage

    init(_ url: URL) throws {
        guard
            let source = CGImageSourceCreateWithURL(url as CFURL, nil),
            let type = CGImageSourceGetType(source),
            let image = CGImageSourceCreateImageAtIndex(source, 0, nil)
        else {
            throw DecodeError.unreadable(url)
        }
        typeIdentifier = type as String
        properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any] ?? [:]
        width = properties[kCGImagePropertyPixelWidth] as? Int ?? image.width
        height = properties[kCGImagePropertyPixelHeight] as? Int ?? image.height
        self.image = image
    }

    var gps: [CFString: Any]? { properties[kCGImagePropertyGPSDictionary] as? [CFString: Any] }
    var exif: [CFString: Any]? { properties[kCGImagePropertyExifDictionary] as? [CFString: Any] }
    var tiff: [CFString: Any]? { properties[kCGImagePropertyTIFFDictionary] as? [CFString: Any] }

    /// RGBA at a pixel, measured from the top-left corner.
    func rgba(x: Int, y: Int) -> [UInt8] {
        var pixel = [UInt8](repeating: 0, count: 4)
        pixel.withUnsafeMutableBytes { buffer in
            guard
                let context = CGContext(
                    data: buffer.baseAddress, width: 1, height: 1, bitsPerComponent: 8,
                    bytesPerRow: 4,
                    space: CGColorSpace(name: CGColorSpace.sRGB) ?? CGColorSpaceCreateDeviceRGB(),
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
            else { return }
            // Shift the image so the wanted pixel lands on the 1×1 canvas.
            context.draw(
                image,
                in: CGRect(
                    x: -x, y: -(image.height - 1 - y), width: image.width, height: image.height))
        }
        return pixel
    }

    enum DecodeError: Error {
        case unreadable(URL)
    }
}

/// Writes a 64×48 JPEG whose EXIF says "rotate 90° clockwise to display", so
/// it shows as 48×64.
func writeRotatedJPEG(to url: URL) throws {
    let source = try DecodedImage(Fixtures.image(FormatCatalog.png))
    guard
        let destination = CGImageDestinationCreateWithURL(
            url as CFURL, "public.jpeg" as CFString, 1, nil)
    else { throw DecodedImage.DecodeError.unreadable(url) }
    CGImageDestinationAddImage(
        destination, source.image, [kCGImagePropertyOrientation: 6] as CFDictionary)
    guard CGImageDestinationFinalize(destination) else {
        throw DecodedImage.DecodeError.unreadable(url)
    }
}
